import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import type { ActionConversationRenderGroup } from './action_conversation_render_groups'

const MIN_RESERVED_BLOCK_COUNT = 1

export interface ActionConversationReservationState {
    active: boolean
    conversationPath: string | null
    inputKey: string
    permanentKeys: Set<string>
    runningKeys: Set<string>
    slotCount: number
}

function runIsActive(status: PopupRunStatus) {
    return status === 'queued' || status === 'running' || status === 'waitingForInput'
}

function groupIsRunning(group: ActionConversationRenderGroup) {
    if (group.kind === 'completedToolCalls' || group.entry.kind !== 'event') return false

    return group.entry.status === 'inProgress'
        || group.entry.status === 'running'
        || group.entry.status === 'started'
}

function reservationInputKey(
    conversationPath: string | null,
    groups: ActionConversationRenderGroup[],
    active: boolean,
) {
    return JSON.stringify([conversationPath, active, groups.map((group) => [group.key, groupIsRunning(group)])])
}

/** Creates empty presentation state for chat-bottom reservation tracking. */
export function createActionConversationReservationState(): ActionConversationReservationState {
    return {
        active: false,
        conversationPath: null,
        inputKey: '',
        permanentKeys: new Set(),
        runningKeys: new Set(),
        slotCount: 0,
    }
}

/** Advances reserved-slot state from visible render-group lifecycle changes. */
export function updateActionConversationReservation(
    previous: ActionConversationReservationState,
    conversationPath: string | null,
    groups: ActionConversationRenderGroup[],
    status: PopupRunStatus,
) {
    const active = runIsActive(status)
    const inputKey = reservationInputKey(conversationPath, groups, active)
    if (inputKey === previous.inputKey) return previous
    if (!active) return { ...createActionConversationReservationState(), inputKey }

    const runningKeys = new Set(groups.filter(groupIsRunning).map(({ key }) => key))
    const permanentKeys = new Set(groups.filter((group) => !groupIsRunning(group)).map(({ key }) => key))
    const sessionChanged = !previous.active || previous.conversationPath !== conversationPath
    if (sessionChanged) {
        return {
            active,
            conversationPath,
            inputKey,
            permanentKeys,
            runningKeys,
            slotCount: Math.max(MIN_RESERVED_BLOCK_COUNT, runningKeys.size),
        }
    }

    const newPermanentCount = [...permanentKeys].filter((key) => !previous.permanentKeys.has(key)).length
    const retainedRunningCount = [...runningKeys].filter((key) => previous.runningKeys.has(key)).length
    const newRunningCount = runningKeys.size - retainedRunningCount
    const reducedSlotCount = Math.max(MIN_RESERVED_BLOCK_COUNT, previous.slotCount - newPermanentCount)
    const availableSlotCount = Math.max(0, reducedSlotCount - retainedRunningCount)
    const slotCount = reducedSlotCount + Math.max(0, newRunningCount - availableSlotCount)

    return { active, conversationPath, inputKey, permanentKeys, runningKeys, slotCount }
}

/** Returns currently unused slots rendered as bottom placeholders. */
export function reservedActionConversationBlockCount(state: ActionConversationReservationState) {
    return Math.max(0, state.slotCount - state.runningKeys.size)
}

import { describe, expect, it } from 'vitest'
import type { AgentConversationEventEntry, AgentConversationMessageEntry } from '../../../data/data_types'
import type { ActionConversationRenderGroup } from './action_conversation_render_groups'
import {
    createActionConversationReservationState,
    reservedActionConversationBlockCount,
    updateActionConversationReservation,
} from './action_conversation_reservation'

type EntryRenderGroup = Extract<ActionConversationRenderGroup, { kind: 'entry' }>
type EventEntryRenderGroup = EntryRenderGroup & { entry: AgentConversationEventEntry }

function runningGroup(key: string): EventEntryRenderGroup {
    const entry: AgentConversationEventEntry = {
        content: key,
        id: key,
        kind: 'event',
        providerItemId: key,
        status: 'inProgress',
        timestamp: 'now',
        type: 'reasoning',
    }

    return { entry, key, kind: 'entry' }
}

function permanentMessageGroup(key: string): EntryRenderGroup {
    const entry: AgentConversationMessageEntry = {
        content: key,
        id: key,
        kind: 'message',
        role: 'assistant',
        timestamp: 'now',
    }

    return { entry, key, kind: 'entry' }
}

describe('action conversation reservation', () => {
    it('reserves one block for an active conversation without running blocks', () => {
        const state = updateActionConversationReservation(
            createActionConversationReservationState(),
            'conversation.json',
            [],
            'running',
        )

        expect(reservedActionConversationBlockCount(state)).toBe(1)
    })

    it('restores simultaneous running slots and lets permanent blocks consume surplus', () => {
        const runningGroups = [runningGroup('first'), runningGroup('second')]
        const running = updateActionConversationReservation(
            createActionConversationReservationState(),
            'conversation.json',
            runningGroups,
            'running',
        )
        const disappeared = updateActionConversationReservation(running, 'conversation.json', [], 'running')
        const permanent = updateActionConversationReservation(
            disappeared,
            'conversation.json',
            [permanentMessageGroup('message')],
            'running',
        )

        expect(reservedActionConversationBlockCount(running)).toBe(0)
        expect(reservedActionConversationBlockCount(disappeared)).toBe(2)
        expect(reservedActionConversationBlockCount(permanent)).toBe(1)
    })

    it('does not treat in-place updates or existing tool-group regrouping as new permanent blocks', () => {
        const firstTool = runningGroup('first-tool')
        firstTool.entry.status = 'completed'
        const initial = updateActionConversationReservation(
            createActionConversationReservationState(),
            'conversation.json',
            [firstTool],
            'running',
        )
        const grouped: ActionConversationRenderGroup = {
            entries: [firstTool.entry, { ...firstTool.entry, id: 'second-tool', providerItemId: 'second-tool' }],
            key: 'first-tool',
            kind: 'completedToolCalls',
        }
        const updated = updateActionConversationReservation(initial, 'conversation.json', [grouped], 'running')

        expect(updated).toBe(initial)
        expect(reservedActionConversationBlockCount(updated)).toBe(1)
    })

    it('resets reservation when conversation changes or becomes terminal', () => {
        const running = updateActionConversationReservation(
            createActionConversationReservationState(),
            'first.json',
            [runningGroup('first'), runningGroup('second')],
            'running',
        )
        const disappeared = updateActionConversationReservation(running, 'first.json', [], 'running')
        const switched = updateActionConversationReservation(disappeared, 'second.json', [], 'running')
        const terminal = updateActionConversationReservation(switched, 'second.json', [], 'completed')

        expect(reservedActionConversationBlockCount(disappeared)).toBe(2)
        expect(reservedActionConversationBlockCount(switched)).toBe(1)
        expect(reservedActionConversationBlockCount(terminal)).toBe(0)
    })
})

import type {
    AgentConversationEntry,
    AgentConversationEventEntry,
} from '../../../data/data_types'
import { eventIdentity } from './event_display'

const TOOL_CALL_EVENT_TYPES = new Set([
    'collabAgentToolCall',
    'commandExecution',
    'dynamicToolCall',
    'fileChange',
    'imageView',
    'mcpToolCall',
    'webSearch',
])
const DEFAULT_SUB_AGENT_LABEL = 'Sub agent'

export type ActionConversationRenderGroup = {
    entries: AgentConversationEventEntry[]
    key: string
    kind: 'completedToolCalls'
} | {
    entry: AgentConversationEntry
    key: string
    kind: 'entry'
} | {
    entry: AgentConversationEventEntry
    groups: ActionConversationRenderGroup[]
    key: string
    kind: 'subAgent'
    label: string
    runningCount: number
}

function isToolCall(entry: AgentConversationEventEntry) {
    return TOOL_CALL_EVENT_TYPES.has(entry.type) || entry.type.startsWith('tool.')
}

function isCompletedToolCall(entry: AgentConversationEventEntry) {
    return entry.status === 'completed' && isToolCall(entry)
}

function appendCompletedToolCallRun(
    groups: ActionConversationRenderGroup[],
    entries: AgentConversationEventEntry[],
) {
    if (entries.length === 0) return
    if (entries.length === 1) {
        const [entry] = entries
        groups.push({ entry, key: eventIdentity(entry), kind: 'entry' })
        return
    }

    groups.push({ entries, key: eventIdentity(entries[0]), kind: 'completedToolCalls' })
}

function parsedToolInput(content: string) {
    try {
        const parsed: unknown = JSON.parse(content)
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null

        return parsed as Record<string, unknown>
    } catch {
